import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';

import '../../ai/models/ai_execution_plan.dart';

const Object _variationSentinel = Object();

/// Represents a distinct widget variation generated by the Criador de Widgets com IA.
class WidgetVariation {
  final String id;
  final String title;
  final String styleTag; // e.g. "Glassmorphism Oval", "Bento Grid Profile", "Hero Banner"
  final String description;
  final String dartCode;
  final IconData? icon;
  final String techApproach; // e.g. "CircleAvatar + Glow + Row", "ClipRRect + Bento Grid", "Gradient Container + Action Button"
  final List<String> requiredImports;
  final String? extractedWidgetCode;
  final String? callSiteSnippet;
  final AiExecutionPlan? plan;

  const WidgetVariation({
    required this.id,
    required this.title,
    required this.styleTag,
    required this.description,
    required this.dartCode,
    this.icon,
    required this.techApproach,
    this.requiredImports = const [],
    this.extractedWidgetCode,
    this.callSiteSnippet,
    this.plan,
  });

  WidgetVariation copyWith({
    String? id,
    String? title,
    String? styleTag,
    String? description,
    String? dartCode,
    Object? icon = _variationSentinel,
    String? techApproach,
    List<String>? requiredImports,
    Object? extractedWidgetCode = _variationSentinel,
    Object? callSiteSnippet = _variationSentinel,
    Object? plan = _variationSentinel,
  }) {
    return WidgetVariation(
      id: id ?? this.id,
      title: title ?? this.title,
      styleTag: styleTag ?? this.styleTag,
      description: description ?? this.description,
      dartCode: dartCode ?? this.dartCode,
      icon: identical(icon, _variationSentinel) ? this.icon : icon as IconData?,
      techApproach: techApproach ?? this.techApproach,
      requiredImports: requiredImports != null
          ? List<String>.unmodifiable(requiredImports)
          : this.requiredImports,
      extractedWidgetCode:
          identical(extractedWidgetCode, _variationSentinel)
              ? this.extractedWidgetCode
              : extractedWidgetCode as String?,
      callSiteSnippet: identical(callSiteSnippet, _variationSentinel)
          ? this.callSiteSnippet
          : callSiteSnippet as String?,
      plan: identical(plan, _variationSentinel)
          ? this.plan
          : plan as AiExecutionPlan?,
    );
  }

  Map<String, dynamic> toJson() {
    return {
      'id': id,
      'title': title,
      'styleTag': styleTag,
      'description': description,
      'dartCode': dartCode,
      'techApproach': techApproach,
      if (requiredImports.isNotEmpty)
        'requiredImports': List<String>.from(requiredImports),
      if (extractedWidgetCode != null)
        'extractedWidgetCode': extractedWidgetCode,
      if (callSiteSnippet != null) 'callSiteSnippet': callSiteSnippet,
      if (plan != null) 'plan': plan!.toJson(),
    };
  }

  factory WidgetVariation.fromJson(Map<String, dynamic> json, {IconData? icon}) {
    final rawImports = json['requiredImports'] ?? json['required_imports'];
    final imports = <String>[];
    if (rawImports is Iterable) {
      for (final entry in rawImports) {
        final value = entry?.toString().trim();
        if (value != null && value.isNotEmpty && value != 'null') {
          imports.add(value);
        }
      }
    } else if (rawImports is String && rawImports.trim().isNotEmpty) {
      for (final part in rawImports.split(RegExp(r'[\r\n,;]+'))) {
        final value = part.trim();
        if (value.isNotEmpty && value != 'null') {
          imports.add(value);
        }
      }
    }

    final rawExtracted =
        json['extractedWidgetCode'] ?? json['extracted_widget_code'];
    final extractedWidgetCode =
        rawExtracted is String && rawExtracted.trim().isNotEmpty
            ? rawExtracted
            : null;

    final rawCallSite = json['callSiteSnippet'] ?? json['call_site_snippet'];
    final callSiteSnippet =
        rawCallSite is String && rawCallSite.trim().isNotEmpty
            ? rawCallSite
            : null;

    final rawPlan = json['plan'];
    AiExecutionPlan? parsedPlan;
    if (rawPlan is AiExecutionPlan) {
      parsedPlan = rawPlan;
    } else if (rawPlan is Map<String, dynamic>) {
      parsedPlan = AiExecutionPlan.fromJson(rawPlan);
    } else if (rawPlan is Map) {
      parsedPlan = AiExecutionPlan.fromJson(Map<String, dynamic>.from(rawPlan));
    }

    return WidgetVariation(
      id: json['id'] as String? ?? '',
      title: json['title'] as String? ?? '',
      styleTag: json['styleTag'] as String? ?? '',
      description: json['description'] as String? ?? '',
      dartCode: json['dartCode'] as String? ?? '',
      icon: icon,
      techApproach: json['techApproach'] as String? ?? '',
      requiredImports: imports.isEmpty
          ? const []
          : List<String>.unmodifiable(imports),
      extractedWidgetCode: extractedWidgetCode,
      callSiteSnippet: callSiteSnippet,
      plan: parsedPlan,
    );
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) return true;
    return other is WidgetVariation &&
        other.id == id &&
        other.title == title &&
        other.styleTag == styleTag &&
        other.description == description &&
        other.dartCode == dartCode &&
        other.icon == icon &&
        other.techApproach == techApproach &&
        listEquals(other.requiredImports, requiredImports) &&
        other.extractedWidgetCode == extractedWidgetCode &&
        other.callSiteSnippet == callSiteSnippet &&
        other.plan == plan;
  }

  @override
  int get hashCode => Object.hash(
        id,
        title,
        styleTag,
        description,
        dartCode,
        icon,
        techApproach,
        Object.hashAll(requiredImports),
        extractedWidgetCode,
        callSiteSnippet,
        plan,
      );

  @override
  String toString() =>
      'WidgetVariation(id: $id, title: "$title", styleTag: "$styleTag", techApproach: "$techApproach")';
}
